INSERT IGNORE INTO role_permissions (role_id, permission_id) SELECT r.id, p.id FROM roles r JOIN permissions p ON p.code IN ('partnership.view', 'partnership.manage', 'business_directory.view', 'business_directory.manage') WHERE r.name = 'ADMIN';
INSERT IGNORE INTO role_assignable_permissions (role_id, permission_id) SELECT r.id, p.id FROM roles r JOIN permissions p ON p.code IN ('partnership.view', 'partnership.manage', 'business_directory.view', 'business_directory.manage') WHERE r.name = 'ADMIN';
