INSERT IGNORE INTO role_permissions (role_id, permission_id) SELECT r.id, p.id FROM roles r JOIN permissions p ON p.code IN ('whatsapp.view', 'whatsapp.manage', 'member_account.view', 'member_account.manage') WHERE r.name = 'ADMIN';
