INSERT IGNORE INTO role_template_permissions (template_id, permission_id) SELECT t.id, p.id FROM role_templates t JOIN permissions p ON p.code IN ('whatsapp.view', 'whatsapp.manage', 'member_account.view', 'member_account.manage') WHERE t.name = 'ADMIN';
INSERT IGNORE INTO role_template_assignable_permissions (template_id, permission_id) SELECT t.id, p.id FROM role_templates t JOIN permissions p ON p.code IN ('whatsapp.view', 'whatsapp.manage', 'member_account.view', 'member_account.manage') WHERE t.name = 'ADMIN';
INSERT IGNORE INTO role_assignable_permissions (role_id, permission_id) SELECT r.id, p.id FROM roles r CROSS JOIN permissions p WHERE r.name != 'SUPER_ADMIN' AND p.category != 'superadmin';
